constexpr bool cuts_ok() {
    for (uint32_t m = 0; m < kMeetingPackets.size(); ++m) {
        if (kMeetingPackets[m] == 0 || kMeetingPacketBytes[m] % 16 || kMeetingPacketBytes[m] > 2048) return false;
        if (uint64_t(kMeetingPackets[m]) * kMeetingPacketBytes[m] < kMeetingChunkBytes[m]) return false;
        if (uint64_t(kMeetingPackets[m] - 1) * kMeetingPacketBytes[m] >= kMeetingChunkBytes[m]) return false;
    }
    return true;
}
static_assert(cuts_ok(), "coll_routes: a meeting's packet cut does not cover its chunk within 2 KiB packets");
// ---- static checks: every tree spans the group, parents and children agree, depths are the shortest routes ----
constexpr bool trees_ok() {
    for (uint32_t r = 0; r < 8; ++r) {
        if (kTree[r][r].parent != -1 || kTree[r][r].depth != 0) return false;
        uint32_t edges = 0;
        for (uint32_t c = 0; c < 8; ++c) {
            const auto& n = kTree[r][c];
            if (c != r) {
                if (n.parent < 0 || n.parent >= 8) return false;
                if (kTree[r][n.parent].depth + 1 != n.depth) return false;
                bool listed = false;
                for (uint32_t k = 0; k < kTree[r][n.parent].n_children; ++k) listed |= kTree[r][n.parent].child[k] == int8_t(c);
                if (!listed) return false;
            }
            const uint32_t rr = r / 4, rc = r % 4, cr = c / 4, cc = c % 4;
            const uint32_t dc = (cc + 4 - rc) % 4;
            const uint32_t ring = dc < 4 - dc ? dc : 4 - dc;
            if (n.depth != (rr != cr ? 1u : 0u) + ring) return false;
            if (n.depth > kTreeDepthMax) return false;
            edges += n.n_children;
        }
        if (edges != 7) return false;
    }
    return true;
}
static_assert(trees_ok(), "coll_routes: a BFS tree is inconsistent");
constexpr bool hand_ok() {
    for (const auto& h : kHandOver) {
        uint32_t r = h.from_row, c = h.from_col;
        for (uint32_t k = 0; k < h.hops; ++k) {
            switch (h.route[k]) {
                case Dir::N: r = (r + 7) % 8; break;
                case Dir::S: r = (r + 1) % 8; break;
                case Dir::E: c = (c + 1) % 4; break;
                case Dir::W: c = (c + 3) % 4; break;
                default: return false;
            }
        }
        if (r != h.to_row || c != h.to_col) return false;
        if (h.from_row / 2 != h.from_group || h.to_row / 2 != (h.from_group + 1) % kGroups) return false;
    }
    return true;
}
static_assert(hand_ok(), "coll_routes: a hand-over route does not reach its pair");

